'use strict';
const { app, BrowserWindow, ipcMain, session } = require('electron');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { DshViewManager } = require('../../backend/dsh-view.cjs');
const root = path.resolve(process.env.ADH_MODAL_VISIBILITY_ROOT || '');
if (!/^adh-modal-visibility-/.test(path.basename(root))) throw new Error('An isolated modal test directory is required.');
app.setPath('userData', path.join(root, 'profile')); app.disableHardwareAcceleration();
let win, manager;
app.whenReady().then(async () => {
  let networkRequests = 0;
  session.defaultSession.webRequest.onBeforeRequest({ urls: ['http://*/*', 'https://*/*'] }, (_details, callback) => { networkRequests++; callback({ cancel: true }); });
  win = new BrowserWindow({ show: false, width: 1000, height: 800, webPreferences: { nodeIntegration: true, contextIsolation: false, backgroundThrottling: false } });
  const file = path.join(root, 'fixture.html');
  fs.writeFileSync(file, '<!doctype html><html><body><div class="app-shell"><aside class="sidebar"></aside><div id="dshViewContainer"></div></div><dialog id="model"><h1>模型设置</h1><input id="modelInput"><button id="closeModel" onclick="this.closest(\'dialog\').close()">关闭</button></dialog><dialog id="batch">批量接入</dialog><div id="legacy" class="modal-backdrop"></div></body></html>');
  await win.loadFile(file);
  manager = new DshViewManager(() => win, () => 'data:text/html,<html><body>Agent fixture</body></html>');
  manager.setBounds({ x: 12, y: 60, width: 850, height: 650 });
  manager.attach();
  const js = source => win.webContents.executeJavaScript(source, true);
  const wait = async predicate => { for (let i = 0; i < 100; i++) { if (await predicate()) return; await new Promise(resolve => setTimeout(resolve, 10)); } throw new Error('Native modal visibility did not settle.'); };
  await wait(() => manager.view.webContents.getURL().startsWith('data:'));
  await manager.view.webContents.executeJavaScript('window.fixtureSession = 42');
  const contentsId = manager.view.webContents.id;
  const changes = [];
  ipcMain.handle('fixture:dsh-hidden', (_event, hidden) => { changes.push(hidden); manager.setHidden(hidden); });
  const source = fs.readFileSync(path.join(__dirname, '../../app-v2.js'), 'utf8');
  const modalStart = source.indexOf('  let dshModalHidden = null;'), modalEnd = source.indexOf('  let knowledgeWorkbench', modalStart);
  const setupStart = source.indexOf('  function setupDshIntegration() {'), setupEnd = source.indexOf('  async function init()', setupStart);
  assert.ok(modalStart >= 0 && modalEnd > modalStart && setupStart >= 0 && setupEnd > setupStart);
  await js(`(()=>{const {ipcRenderer}=require('electron');const api=window.bycjWorkbench={dshGetState:async()=>({status:'ready'}),dshSetViewHidden:hidden=>ipcRenderer.invoke('fixture:dsh-hidden',hidden),dshOnStateChanged:()=>{},dshOnViewLoaded:()=>{},dshOnHoverLeave:()=>{},dshSetViewInsetLeft:async()=>{}};const $=s=>document.querySelector(s),state={currentView:'adh-agent'},DSH_EDGE_INSET=12;const updateDshViewBounds=()=>{},updateAgentRightInset=()=>{},updateAgentTopInset=()=>{},markDshViewLoaded=()=>{},renderDshState=()=>{},toast=()=>{};${source.slice(modalStart,modalEnd)}${source.slice(setupStart,setupEnd)}setupDshIntegration();})()`);
  const result = {};
  await js('document.getElementById("model").showModal()'); await wait(() => !manager.view.getVisible());
  await js('document.getElementById("modelInput").value="synthetic-setting"'); result.modelDialog = await js('document.getElementById("modelInput").value==="synthetic-setting"');
  manager.setBounds({ x: 20, y: 80, width: 800, height: 600 }); manager.setLeftInset(30);
  result.resizeWhileHidden = !manager.view.getVisible();
  await js('document.getElementById("batch").showModal()'); await js('document.getElementById("batch").close()');
  await new Promise(resolve => setTimeout(resolve, 30)); assert.equal(manager.view.getVisible(), false);
  await js('document.getElementById("closeModel").click()'); await wait(() => manager.view.getVisible()); result.nestedDialogs = true;
  assert.deepEqual(manager.view.getBounds(), { x: 50, y: 80, width: 770, height: 600 });
  result.sameSession = manager.view.webContents.id === contentsId && await manager.view.webContents.executeJavaScript('window.fixtureSession===42');
  await js('document.getElementById("legacy").classList.add("is-open")'); await wait(() => !manager.view.getVisible());
  await js('document.getElementById("legacy").classList.remove("is-open")'); await wait(() => manager.view.getVisible()); result.legacyModal = true;
  manager.detach(); await js('document.getElementById("model").showModal()'); await wait(() => manager.hidden);
  manager.attach(); assert.equal(manager.view.getVisible(), false);
  await js('document.getElementById("model").close()'); await wait(() => manager.view.getVisible()); result.delayedAttach = true;
  await js('document.getElementById("model").showModal()'); await wait(() => !manager.view.getVisible());
  await js('document.getElementById("model").remove()'); await wait(() => manager.view.getVisible()); result.removedDialog = true;
  assert.ok(changes.length < 15, 'Unrelated mutations must not repeatedly send visibility IPC.');
  console.log('ADH_MODAL_RESULT ' + JSON.stringify({ ...result, networkRequests }));
}).catch(error => { console.error(error); process.exitCode = 1; }).finally(() => { manager?.detach(); win?.destroy(); app.quit(); });
